async function renderFaith(){const date=$('#faithDate')?.value||today();if(!$('#faithDate'))return;$('#faithDate').value=date;const logs=await api('/faith?date='+date);const done=new Set(logs.filter(x=>x.completed).map(x=>x.activity));$('#faithCount').textContent=done.size+' / '+faithActivities.length+' COMPLETE';$('#faithChecklist').innerHTML=faithActivities.map(([key,label])=>'<label class="faith-check '+(done.has(key)?'done':'')+'"><input type="checkbox" data-faith-activity="'+key+'" '+(done.has(key)?'checked':'')+'><span>'+label+'</span></label>').join('');$$('[data-faith-activity]').forEach(input=>input.onchange=async()=>{await api('/faith',{method:'PATCH',body:JSON.stringify({date,activity:input.dataset.faithActivity,completed:input.checked})});renderFaith();renderCalendar()});}
