async function renderCalendar(){if(!$('#calendarGrid'))return;const year=calendarMonth.getFullYear(),month=String(calendarMonth.getMonth()+1).padStart(2,'0');$('#calendarMonthLabel').textContent=calendarMonth.toLocaleDateString('en-US',{month:'long',year:'numeric'});const result=await api('/calendar?month='+year+'-'+month);calendarData=result.days||[];const byDate=new Map(calendarData.map(d=>[d.date,d]));const start=(calendarMonth.getDay()+6)%7,daysInMonth=new Date(year,calendarMonth.getMonth()+1,0).getDate();let cells='';for(let i=0;i<start;i++)cells+='<div class="calendar-empty"></div>';for(let day=1;day<=daysInMonth;day++){const date=year+'-'+month+'-'+String(day).padStart(2,'0'),item=byDate.get(date)||{sections:[],perfect:false};cells+='<button type="button" class="calendar-day '+(date===calendarSelected?'selected ':'')+(date===today()?'is-today ':'')+(item.perfect?'perfect':'')+'" data-calendar-date="'+date+'"><span>'+day+'</span><i class="calendar-dots">'+item.sections.map(x=>'<b class="dot '+x+'-dot"></b>').join('')+'</i></button>';}$('#calendarGrid').innerHTML=cells;$$('[data-calendar-date]').forEach(btn=>btn.onclick=()=>{calendarSelected=btn.dataset.calendarDate;renderCalendarDetail();$$('[data-calendar-date]').forEach(x=>x.classList.toggle('selected',x.dataset.calendarDate===calendarSelected))});renderCalendarDetail();const cats=['focus','learning','habits'];if(['islam','christianity'].includes(settings.religion))cats.push('faith');const streaks=result.streaks||{};$('#streakSummary').innerHTML=cats.map(cat=>{const x=streaks[cat]||{current:0,best:0};return '<article class="streak-card"><span class="dot '+cat+'-dot"></span><b>'+({focus:'Focus',learning:'Learning',habits:'Habits',faith:'Faith'}[cat])+'</b><strong>'+x.current+'</strong><small>DAY STREAK · BEST '+x.best+'</small></article>'}).join('');}
function renderCalendarDetail(){const item=calendarData.find(d=>d.date===calendarSelected);$('#calendarSelectedDate').textContent=new Date(calendarSelected+'T12:00:00').toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'});const names={focus:'Focus',learning:'Learning',habits:'Habits',faith:'Faith'};const sections=item?.sections||[];$('#calendarDayDetail').innerHTML=sections.length?sections.map(x=>'<span class="calendar-detail-chip '+x+'">'+names[x]+'</span>').join('')+(item.perfect?'<p class="calendar-perfect-note">Full day — activity recorded across three or more areas.</p>':''):'<p>No activity recorded for this date.</p>'}
