function switchPage(n){if(n==='admin'&&!isAdmin){n='home';}if(n!=='home'&&n!=='admin'&&Object.hasOwn(featureCatalog,n)&&!enabledFeatures().includes(n)){toast('Enable this section in Settings first.');n='home';}if(n==='deen'&&settings.religion!=='islam'&&!isAdmin)n='home';if(n==='faith'&&settings.religion!=='christianity'&&!isAdmin)n='home';$$('.page').forEach(p=>p.classList.toggle('active',p.id==='page-'+n));$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===n));$('#crumb').textContent=({home:'RESIDENCE',learning:'LEARNING STUDIO',tasks:'MY WORK',focus:'FOCUS ROOM',library:'LIBRARY',goals:'THE LONG GAME',deen:'DEEN & QUR’AN',selfcontrol:'SELF-CONTROL',settings:'PREFERENCES',admin:'ADMINISTRATION',rankings:'THE RANKINGS',announcements:'WHAT’S NEW'})[n]||n.toUpperCase();$('#sidebar').classList.remove('open');window.scrollTo({top:0,behavior:'smooth'});if(n==='calendar')renderCalendar();if(n==='rankings')renderLeaderboard();if(n==='faith'&&(settings.religion==='christianity'||isAdmin))renderFaith();if(n==='learning')renderLearning();if(n==='tasks')renderTasks();if(n==='library')renderNotes();if(n==='deen'&&settings.religion==='islam')renderDeen();if(n==='selfcontrol')renderSelfControl();if(n==='admin'&&isAdmin)loadAdminUsers();if(n==='announcements')renderAnnouncements();}
