function renderAnnouncements(){const host=$('#announcementsList');if(!host)return;const visible=atlasAnnouncements.filter(item=>item.published||isAdmin);const unread=visible.filter(item=>item.published&&!announcementReadIds.has(Number(item.id)));$('#announcementBadge').textContent=unread.length>9?'9+':String(unread.length);$('#announcementBadge').classList.toggle('hidden',unread.length===0);$('#announcementCount').textContent=visible.length+' '+(visible.length===1?'UPDATE':'UPDATES');$('#adminAnnouncementComposer').classList.toggle('hidden',!isAdmin);host.innerHTML=visible.length?visible.map(item=>'<article class="announcement-card '+(item.published&&!announcementReadIds.has(Number(item.id))?'is-unread':'')+'"><div class="announcement-card-meta"><span class="announcement-kind kind-'+esc(item.kind)+'">'+({update:'PRODUCT UPDATE',feature:'NEW FEATURE',maintenance:'MAINTENANCE',important:'IMPORTANT'}[item.kind]||'UPDATE')+'</span><time>'+new Date(item.published_at||item.created_at).toLocaleString()+'</time>'+(item.published&&!announcementReadIds.has(Number(item.id))?'<span class="announcement-new-label">NEW</span>':'')+'</div><h2>'+esc(item.title)+'</h2><p>'+esc(item.body)+'</p>'+(item.published&&!announcementReadIds.has(Number(item.id))?'<button class="link-btn" type="button" data-announcement-read="'+esc(item.id)+'">Mark as read ✓</button>':'')+'</article>').join(''):'<section class="panel announcement-empty"><div class="announcement-empty-mark">✳</div><h2>You’re all caught up.</h2><p>When Atlas has something new to share, it will appear here.</p></section>';$('[data-announcement-read]').forEach(button=>button.onclick=()=>markAnnouncementRead(button.dataset.announcementRead));}
