function updateClock(){const d=new Date();$('#clock').textContent=d.toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',hour12:false});const name=settings.display_name||authUser?.user_metadata?.full_name||'there';const username=settings.username||authUser?.user_metadata?.username||'';const greetingName=isAdmin?'ADMIN':name.toUpperCase();$('#greeting').innerHTML=`Welcome back,<br><em>${esc(greetingName)}.</em>`;$('#sideName').textContent=name;$('#sideUsername').textContent=username?`@${username}`:'Private workspace';$('#sideAvatar').textContent=(name.trim()[0]||'A').toUpperCase();$('#topSettings').textContent=(name.trim()[0]||'A').toUpperCase();$('#fullDate').textContent=d.toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric'}).toUpperCase();$('#dayProgress').textContent=`DAY ${Math.ceil((d-new Date(d.getFullYear(),0,0))/86400000)} / 365`;}
function setQuote(){const q=quotes[Math.floor(Math.random()*quotes.length)];$('#dailyQuote').textContent=q[0];$('.quote-author').innerHTML=`${q[1]} <span>✳</span>`}$('#newQuote').onclick=setQuote;
function applyReligionVisibility(){const religion=settings.religion||'none';const dn=$('[data-page="deen"]'),fn=$('[data-page="faith"]'),dp=$('#page-deen'),fp=$('#page-faith');if(dn)dn.classList.toggle('hidden',religion!=='islam'&&!isAdmin);if(fn)fn.classList.toggle('hidden',religion!=='christianity'&&!isAdmin);if(dp)dp.classList.toggle('hidden',religion!=='islam'&&!isAdmin);if(fp)fp.classList.toggle('hidden',religion!=='christianity'&&!isAdmin);const widget=$('[data-widget="deen"]');if(widget)widget.classList.toggle('hidden-widget',religion!=='islam'&&!isAdmin);const legend=$('.calendar-faith-legend');if(legend)legend.classList.toggle('hidden',!['islam','christianity'].includes(religion)&&!isAdmin);}
const featureCatalog={calendar:'Calendar & streaks',deen:'Deen & Qur’an',faith:'Christian faith',selfcontrol:'Self-control',learning:'Learning studio',tasks:'Projects & tasks',focus:'Focus room',library:'Library',goals:'Goals',rankings:'Monthly rankings'};
function defaultFeatures(religion=settings.religion){const base=['calendar','selfcontrol','learning','tasks','focus','library','goals','rankings'];if(religion==='islam')base.push('deen');if(religion==='christianity')base.push('faith');if(isAdmin)base.push('deen','faith');return [...new Set(base)];}
function enabledFeatures(){try{const saved=typeof settings.features==='string'?JSON.parse(settings.features):settings.features;if(Array.isArray(saved))return saved.filter(x=>Object.hasOwn(featureCatalog,x));}catch{}return defaultFeatures();}
function renderFeatureToggles(){const host=$('#featureToggles');if(!host)return;const enabled=new Set(enabledFeatures()),religion=settings.religion||'none';host.innerHTML=Object.entries(featureCatalog).filter(([key])=>!['deen','faith'].includes(key)||isAdmin||key==='deen'&&religion==='islam'||key==='faith'&&religion==='christianity').map(([key,label])=>`<label class="widget-toggle"><span>${label}</span><input type="checkbox" data-feature-toggle="${key}" ${enabled.has(key)?'checked':''}></label>`).join('');$$('[data-feature-toggle]').forEach(input=>input.onchange=async()=>{const next=new Set(enabledFeatures());input.checked?next.add(input.dataset.featureToggle):next.delete(input.dataset.featureToggle);try{settings=await api('/settings',{method:'PATCH',body:JSON.stringify({features:[...next]})});applyFeatureVisibility();renderFeatureToggles();if($('.page.active.hidden'))switchPage('home');toast('Workspace sections updated.')}catch(e){input.checked=!input.checked;toast(e.message)}});}
function applyFeatureVisibility(){const enabled=new Set(enabledFeatures());const canShow=key=>enabled.has(key)&&(key==='deen'?(settings.religion==='islam'||isAdmin):key==='faith'?(settings.religion==='christianity'||isAdmin):true);$$('.nav-item[data-page]').forEach(nav=>{const page=nav.dataset.page,feature=page==='home'||page==='admin'?null:page;if(feature)nav.classList.toggle('hidden',!canShow(feature));});Object.keys(featureCatalog).forEach(key=>{const page=$('#page-'+key);if(page)page.classList.toggle('hidden',!canShow(key));});if($('#page-admin'))$('#adminNav').classList.toggle('hidden',!isAdmin);}
function applySidebarPreference(){const collapsed=settings.sidebar_collapsed==='1';document.body.classList.toggle('sidebar-collapsed',collapsed);const b=$('#sidebarToggle');if(b){b.textContent=collapsed?'⇥':'⇤';b.title=collapsed?'Show sidebar':'Hide sidebar';b.setAttribute('aria-label',b.title);}}
function applyWidgets(){const defaults={week:true,priorities:true,habits:true,rankings:true,northstar:true,next:true,quote:true,quick:true};if(settings.religion==='islam')defaults.deen=true;let saved={};try{saved=typeof settings.widgets==='string'?JSON.parse(settings.widgets):settings.widgets||{};}catch{}const chosen={...defaults,...saved};if(settings.religion!=='islam')delete chosen.deen;Object.entries(chosen).forEach(([k,v])=>{const el=$(`[data-widget="${k}"]`);if(el)el.classList.toggle('hidden-widget',!v)});$('#widgetToggles').innerHTML=Object.entries(defaults).map(([k,v])=>`<label class="widget-toggle">${({week:'Weekly focus chart',priorities:'Today’s priorities',habits:'Daily rituals',deen:'Deen & Qur’an summary',northstar:'North star',next:'Next learning step',quote:'Daily reminder',quick:'Quick capture',rankings:'Monthly rankings'})[k]}<input type="checkbox" data-widget-toggle="${k}" ${chosen[k]?'checked':''}></label>`).join('');$$('[data-widget-toggle]').forEach(c=>c.onchange=async()=>{chosen[c.dataset.widgetToggle]=c.checked;try{settings=await api('/settings',{method:'PATCH',body:JSON.stringify({widgets:chosen})});applyWidgets();}catch(e){toast(e.message)}});}
async function load(){try{[tasks,modules,learningPaths,sessions,notes,goals,settings]=await Promise.all([api('/tasks'),api('/modules'),api('/learning/paths'),api('/sessions'),api('/notes'),api('/goals'),api('/settings')]);habits=await api('/habits?date='+today());updateClock();setInterval(updateClock,30000);$('#sessionDate')?.setAttribute('value',today());$('#northStarText').textContent=settings.north_star||'Set an intention that matters to you.';$('#displayNameInput').value=settings.display_name||authUser?.user_metadata?.full_name||'';$('#usernameInput').value=settings.username||authUser?.user_metadata?.username||'';$('#northStarInput').value=settings.north_star||'';$('#dailyTargetInput').value=settings.daily_target||80;$('#leaderboardNameInput').value=settings.leaderboard_name||'';$('#leaderboardPublicInput').checked=settings.leaderboard_public!=='0';if(!settings.religion){settings.religion=authUser?.user_metadata?.religion||(isAdmin?'islam':'none');settings=await api('/settings',{method:'PATCH',body:JSON.stringify({religion:settings.religion})});}if(!settings.theme){settings.theme=authUser?.user_metadata?.theme||localStorage.getItem('personalOsTheme')||'nocturnal-amethyst';settings=await api('/settings',{method:'PATCH',body:JSON.stringify({theme:settings.theme})});}if(!settings.features){const saved=authUser?.user_metadata?.enabled_features;settings=await api('/settings',{method:'PATCH',body:JSON.stringify({features:Array.isArray(saved)?saved:defaultFeatures(settings.religion)})});}$('#religionInput').value=settings.religion||'none';applyReligionVisibility();applyTheme(settings.theme||localStorage.getItem('personalOsTheme')||'nocturnal-amethyst',false);renderThemePicker();renderAll();applyWidgets();applyReligionVisibility();applyFeatureVisibility();renderFeatureToggles();applySidebarPreference();}catch(e){console.error('Residence load failed:',e);toast('Could not load your residence: '+e.message)}}
function renderAll(){renderOverview();renderLeaderboard();renderTasks();renderLearning();renderSessions();renderNotes();renderGoals();renderHabits();if(settings.religion==='islam'||isAdmin)renderDeen();if(settings.religion==='christianity'||isAdmin)renderFaith();renderCalendar();}
async function renderLeaderboard(){
 const host=$('#leaderboardPodium'),full=$('#leaderboardFullList');
 if(!host)return;
 try{
  const data=await api('/leaderboard');leaderboardData=data;
  const monthLabel=new Date(data.month+'-01T12:00:00').toLocaleDateString('en-US',{month:'long',year:'numeric'}).toUpperCase();
  if($('#leaderboardMonth'))$('#leaderboardMonth').textContent=monthLabel;
  if($('#rankingsTitle'))$('#rankingsTitle').textContent=monthLabel+' rankings';
  const top=data.top||[];
  host.innerHTML=top.length?top.slice(0,3).map((x,i)=>'<div class="leaderboard-podium-row '+(x.isYou?'is-you':'')+'"><span class="leaderboard-place">'+['🥇','🥈','🥉'][i]+'</span><span class="leaderboard-person"><b>'+esc(x.display)+'</b><small>#'+x.rank+'</small></span><strong>'+Number(x.xp).toLocaleString()+' XP</strong></div>').join(''):'<div class="empty">The season has started. Earn XP to claim the first place.</div>';
  const mine=data.mine||{rank:null,xp:0,totalXp:0,public:true};
  const yourLine=mine.public?(mine.rank?'Your position · #'+mine.rank:'You have not earned a rank yet'):'You are hidden from public rankings.';
  const yourHtml='<span>'+yourLine+'</span><b>'+Number(mine.xp||0).toLocaleString()+' XP this month</b>';
  if($('#leaderboardYou'))$('#leaderboardYou').innerHTML=yourHtml;
  if($('#leaderboardFullYou'))$('#leaderboardFullYou').innerHTML=yourHtml+' <span class="leaderboard-lifetime">· '+Number(mine.totalXp||0).toLocaleString()+' lifetime XP</span>';
  if(full)full.innerHTML=top.length?top.map(x=>'<div class="leaderboard-full-row '+(x.isYou?'is-you':'')+'"><span class="leaderboard-rank">#'+x.rank+'</span><b>'+esc(x.display)+'</b><strong>'+Number(x.xp).toLocaleString()+' XP</strong></div>').join(''):'<div class="empty">No points have been earned this month yet.</div>';
  const champs=data.champions||[];
  if($('#leaderboardChampions'))$('#leaderboardChampions').innerHTML=champs.length?champs.map(x=>'<div class="champion-row"><span>🏆</span><b>'+new Date(x.month+'-01T12:00:00').toLocaleDateString('en-US',{month:'long',year:'numeric'})+'</b><span>'+esc(x.winner?.display||'—')+'</span><strong>'+Number(x.winner?.xp||0).toLocaleString()+' XP</strong></div>').join(''):'<p class="subtle-count">The first champion will be recorded when this month ends.</p>';
 }catch(error){
  console.warn('Leaderboard unavailable:',error.message);
  host.innerHTML='<p class="subtle-count">Rankings are temporarily unavailable.</p>';
  if(full)full.innerHTML='<p class="subtle-count">Rankings are temporarily unavailable.</p>';
  if($('#leaderboardYou'))$('#leaderboardYou').textContent='Your monthly position will appear here.';
 }
}
function renderOverview(){api('/overview').then(o=>{const pct=o.moduleTotal?Math.round(o.completed/o.moduleTotal*100):0;$('#todayMinutes').textContent=o.todayMin;$('#targetLabel').textContent=`of ${o.dailyTarget} min intention`;$('#todayProgress').style.width=Math.min(100,o.todayMin/o.dailyTarget*100)+'%';$('#weekMinutes').textContent=o.weekMin;$('#weekHours').textContent=(o.weekMin/60).toFixed(1)+' hrs';$('#learningPercent').textContent=pct;$('#learningLabel').textContent=`${o.completed} of ${o.moduleTotal} checkpoints` ;$('#learningProgress').style.width=pct+'%';$('#streak').textContent=o.streak;if($('#learningPctLarge'))$('#learningPctLarge').textContent=pct+'%';$('#ringPct').textContent=pct+'%';$('#learningRing').style.background=`conic-gradient(var(--goal) ${pct*3.6}deg,#343943 0)`;$('#weekTotal').textContent=`${o.weekMin} MINUTES LOGGED`;
const days=[];for(let i=6;i>=0;i--){const d=new Date();d.setDate(d.getDate()-i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;days.push({key,label:d.toLocaleDateString('en-US',{weekday:'short'}).toUpperCase(),min:o.sessions.find(s=>s.session_date===key)?.minutes||0})}const max=Math.max(60,...days.map(d=>d.min));$('#weekChart').innerHTML=days.map(d=>`<div class="week-day ${d.key===today()?'today':''}"><span class="bar-value">${d.min||''}</span><div class="bar-track"><div class="bar-fill" style="height:${d.min/max*100}%"></div></div><span class="bar-label">${d.label}</span></div>`).join('');const open=tasks.filter(t=>!t.done).slice(0,5);$('#todayTasks').innerHTML=open.length?open.map(t=>`<div class="priority-row"><input class="check" type="checkbox" data-task-check="${t.id}"><div class="priority-copy"><strong>${esc(t.title)}</strong><small>${esc(t.category)}${t.due_date?' · '+localDate(t.due_date):''}</small></div><span class="priority-tag">${esc(t.category)}</span></div>`).join(''):'<div class="empty">No open priorities. Give yourself some breathing room.</div>';$$('[data-task-check]').forEach(c=>c.onchange=()=>toggleTask(c.dataset.taskCheck,c.checked));const next=learningPaths.flatMap(p=>p.lessons||[]).find(l=>l.status!=='Completed');$('#nextModuleTitle').textContent=next?.title||'Your next chapter';}).catch(console.error)}
function renderTasks(){const list=tasks.filter(t=>filter==='all'||(filter==='open'&&!t.done)||(filter==='done'&&t.done));$('#taskCount').textContent=`${list.length} ${list.length===1?'ITEM':'ITEMS'}`;$('#taskList').innerHTML=list.length?list.map(t=>`<article class="task-row ${t.done?'done':''}"><input class="check" type="checkbox" data-task-check="${t.id}" ${t.done?'checked':''}><div class="task-copy"><strong>${esc(t.title)}</strong>${t.detail?`<p>${esc(t.detail)}</p>`:''}</div><span class="task-pill">${esc(t.category)}</span>${t.due_date?`<small class="subtle-count">${localDate(t.due_date)}</small>`:''}<button class="delete-btn" data-delete-task="${t.id}" title="Delete task">×</button></article>`).join(''):'<div class="empty">Nothing here yet. Add one meaningful next action.</div>';$$('[data-task-check]').forEach(c=>c.onchange=()=>toggleTask(c.dataset.taskCheck,c.checked));$$('[data-delete-task]').forEach(b=>b.onclick=()=>deleteTask(b.dataset.deleteTask));}
async function toggleTask(id,done){await api('/tasks/'+id,{method:'PATCH',body:JSON.stringify({done})});tasks=await api('/tasks');renderTasks();renderOverview();renderLeaderboard();toast(done?'One less thing to carry.':'Task reopened.')}
async function deleteTask(id){if(!confirm('Delete this task?'))return;await api('/tasks/'+id,{method:'DELETE'});tasks=await api('/tasks');renderTasks();renderOverview();toast('Task removed.')}
$$('.filter').forEach(b=>b.onclick=()=>{$$('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');filter=b.dataset.filter;renderTasks()});
function renderModules(){const groups={};modules.forEach(m=>(groups[m.track]??=[]).push(m));$('#moduleGroups').innerHTML=Object.entries(groups).map(([g,items])=>`<section class="module-group"><div class="group-head"><h3>${esc(g)}</h3><span>${items.filter(x=>x.status==='Completed').length} / ${items.length} COMPLETE</span></div>${items.map(m=>`<div class="module-row"><span class="module-index">${esc(String(m.sort_order).padStart(2,'0'))}</span><div class="module-info"><strong>${esc(m.title)}</strong><small>${m.status==='Completed'?'Checkpoint completed':m.status==='In progress'?'Currently in progress':'Ready when you are'}</small></div><select class="module-status ${m.status==='Completed'?'completed':m.status==='In progress'?'in-progress':''}" data-module="${m.id}"><option ${m.status==='Not started'?'selected':''}>Not started</option><option ${m.status==='In progress'?'selected':''}>In progress</option><option ${m.status==='Completed'?'selected':''}>Completed</option></select></div>`).join('')}</section>`).join('');$$('[data-module]').forEach(s=>s.onchange=async()=>{await api('/modules/'+s.dataset.module,{method:'PATCH',body:JSON.stringify({status:s.value})});modules=await api('/modules');renderModules();renderOverview();toast('Learning progress saved.')})}
function renderLearning(){
 const paths=learningPaths||[],lessons=paths.flatMap(p=>p.lessons||[]),done=lessons.filter(l=>l.status==='Completed').length,minutes=lessons.reduce((n,l)=>n+(l.study_minutes||0),0),pct=lessons.length?Math.round(done/lessons.length*100):0;
 $('#learningPathCount').textContent=paths.length;$('#learningLessonCount').textContent=lessons.length;$('#learningStudyMinutes').textContent=minutes;if($('#learningPctLarge'))$('#learningPctLarge').textContent=pct+'%';$('#ringPct').textContent=pct+'%';$('#learningRing').style.background=`conic-gradient(var(--goal) ${pct*3.6}deg,#343943 0)`;
 $('#learningPaths').innerHTML=paths.length?paths.map(p=>{const ls=p.lessons||[],complete=ls.filter(l=>l.status==='Completed').length,progress=ls.length?Math.round(complete/ls.length*100):0;return `<article class="learning-path-card"><div class="learning-path-head"><div><div class="learning-path-subject">${esc(p.subject||'PERSONAL LEARNING')}</div><h3>${esc(p.title)}</h3></div><button class="delete-btn" data-delete-path="${p.id}" title="Delete path">×</button></div>${p.description?`<p class="learning-path-desc">${esc(p.description)}</p>`:''}<div class="learning-path-progress"><i style="width:${progress}%"></i></div><div class="learning-path-meta"><span>${complete}/${ls.length} LESSONS COMPLETE</span><span>${p.target_date?'TARGET '+esc(p.target_date)+' · ':''}${progress}%</span></div><div class="learning-lessons">${ls.length?ls.map((l,i)=>`<div class="learning-lesson"><i class="lesson-status-dot ${l.status==='Completed'?'done':''}"></i><button class="lesson-open" data-open-lesson="${l.id}">${esc(l.title)}<small>${esc(String(l.status||'Not started').toUpperCase())} · ${esc(l.study_minutes||0)} MIN STUDIED</small></button></div>`).join(''):'<div class="empty">No lessons yet. Add the first lesson to begin.</div>'}</div><div class="learning-card-actions"><button data-add-lesson="${p.id}">＋ Add lesson</button><button data-edit-path="${p.id}">Edit path</button></div></article>`}).join(''):'<div class="empty learning-empty"><strong>Your learning studio is ready.</strong><p>Create your first path for a subject, skill or personal study project.</p><button class="btn-primary" id="emptyNewPath">＋ Create a learning path</button></div>';
 $('#learningPaths').querySelector('#emptyNewPath')?.addEventListener('click',newLearningPath);
 $$('[data-add-lesson]').forEach(b=>b.onclick=()=>newLearningLesson(Number(b.dataset.addLesson)));
 $$('[data-open-lesson]').forEach(b=>b.onclick=()=>openLearningLesson(Number(b.dataset.openLesson)));
 $$('[data-delete-path]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this learning path and all its lessons, resources and study records?')){await api('/learning/paths/'+b.dataset.deletePath,{method:'DELETE'});learningPaths=await api('/learning/paths');renderLearning();renderOverview();toast('Learning path deleted.')}});
 $$('[data-edit-path]').forEach(b=>b.onclick=()=>editLearningPath(Number(b.dataset.editPath)));
}
function newLearningPath(){modal('LEARNING STUDIO / NEW PATH','Create a learning path',`<label>PATH TITLE<input name="title" required maxlength="100" placeholder="e.g. Software Engineering"></label><label>SUBJECT OR CATEGORY<input name="subject" maxlength="60" placeholder="e.g. Development, Deen, Business"></label><label>DESCRIPTION<textarea name="description" rows="3" placeholder="What do you want to understand or be able to do?"></textarea></label><label>TARGET DATE<input name="target_date" type="date"></label>${actions()}`,async e=>{e.preventDefault();await api('/learning/paths',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});learningPaths=await api('/learning/paths');renderLearning();closeModal();toast('Learning path created.')});bindCancel()}
$('#newLearningPath').onclick=newLearningPath;
function editLearningPath(id){const p=learningPaths.find(x=>x.id===id);if(!p)return;modal('LEARNING STUDIO / EDIT PATH','Update your learning path',`<label>PATH TITLE<input name="title" required value="${esc(p.title)}"></label><label>SUBJECT<input name="subject" value="${esc(p.subject||'')}"></label><label>DESCRIPTION<textarea name="description" rows="3">${esc(p.description||'')}</textarea></label><label>TARGET DATE<input name="target_date" type="date" value="${esc(p.target_date||'')}"></label><div class="form-actions"><button type="button" class="btn-cancel" id="cancelModal">Cancel</button><button class="btn-primary">Save changes</button></div>`,async e=>{e.preventDefault();await api('/learning/paths/'+id,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(form)))});learningPaths=await api('/learning/paths');renderLearning();closeModal();toast('Learning path updated.')});bindCancel()}
function newLearningLesson(pathId){modal('LEARNING STUDIO / NEW LESSON','Add a lesson',`<label>LESSON TITLE<input name="title" required placeholder="e.g. Variables and data types"></label><label>LESSON MATERIAL<textarea name="content" rows="6" placeholder="Add an explanation, outline, key concepts or lesson content…"></textarea></label>${actions()}`,async e=>{e.preventDefault();await api('/learning/paths/'+pathId+'/lessons',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});learningPaths=await api('/learning/paths');renderLearning();renderOverview();closeModal();toast('Lesson added.')});bindCancel()}
function openLearningLesson(id){const lesson=learningPaths.flatMap(p=>p.lessons||[]).find(l=>l.id===id);if(!lesson)return;const resources=lesson.resources||[],studyLogs=lesson.study_logs||[];modal('LEARNING STUDIO / LESSON',lesson.title,`<div class="lesson-detail"><label>LESSON TITLE<input name="title" required value="${esc(lesson.title)}"></label><label>LESSON MATERIAL<textarea name="content" rows=5 placeholder="Add an explanation, outline, key concepts or lesson content…">${esc(lesson.content||'')}</textarea></label><label>YOUR NOTES<textarea name="notes" rows="5" placeholder="What did you understand? What needs another look?">${esc(lesson.notes||'')}</textarea></label><label>PROGRESS<select name="status"><option ${lesson.status==='Not started'?'selected':''}>Not started</option><option ${lesson.status==='In progress'?'selected':''}>In progress</option><option ${lesson.status==='Completed'?'selected':''}>Completed</option></select></label><h4>RESOURCES</h4><div class="lesson-resources">${resources.length?resources.map(r=>`<div class="lesson-resource"><a href="${esc(safeHttpUrl(r.url))}" target="_blank" rel="noopener noreferrer">${esc(r.title)} ↗</a><button type="button" data-remove-resource="${r.id}">Remove</button></div>`).join(''):'<span class="subtle-count">No resources attached yet.</span>'}</div><h4>RECENT STUDY RECORDS</h4><div class="lesson-resources">${studyLogs.length?studyLogs.map(log=>`<div class="lesson-resource"><span>${esc(log.log_date)} · ${esc(log.minutes)} min${log.reflection?' — '+esc(log.reflection):''}</span></div>`).join(''):'<span class="subtle-count">No study sessions logged yet.</span>'}</div><div class="lesson-detail-actions"><button type="button" id="addLessonResource">＋ Add resource link</button><button type="button" id="logLessonStudy">＋ Log study time</button><button type="button" id="deleteLearningLesson">Delete lesson</button></div><div class="form-actions"><button type="button" class="btn-cancel" id="cancelModal">Close</button><button class="btn-primary">Save lesson</button></div></div>`,async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));await api('/learning/lessons/'+id,{method:'PATCH',body:JSON.stringify({title:d.title,notes:d.notes,status:d.status,content:d.content})});learningPaths=await api('/learning/paths');renderLearning();renderOverview();renderLeaderboard();closeModal();toast('Lesson saved.')});bindCancel();$('#addLessonResource').onclick=()=>addLessonResource(id);$('#logLessonStudy').onclick=()=>logLessonStudy(id);$('#deleteLearningLesson').onclick=async()=>{if(confirm('Delete this lesson and its resources and study records?')){await api('/learning/lessons/'+id,{method:'DELETE'});learningPaths=await api('/learning/paths');renderLearning();renderOverview();closeModal();toast('Lesson deleted.')}};$$('[data-remove-resource]').forEach(b=>b.onclick=async()=>{await api('/learning/resources/'+b.dataset.removeResource,{method:'DELETE'});learningPaths=await api('/learning/paths');renderLearning();openLearningLesson(id);toast('Resource removed.')})}
function addLessonResource(id){modal('LESSON RESOURCE','Attach a web resource',`<label>RESOURCE NAME<input name="title" required placeholder="e.g. Official documentation"></label><label>URL<input name="url" type="url" required placeholder="https://…"></label>${actions()}`,async e=>{e.preventDefault();await api('/learning/lessons/'+id+'/resources',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});learningPaths=await api('/learning/paths');renderLearning();openLearningLesson(id);toast('Resource attached.')});bindCancel()}
function logLessonStudy(id){modal('LEARNING STUDIO / STUDY LOG','Record a study session',`<label>MINUTES STUDIED<input name="minutes" type="number" min="1" max="600" required placeholder="45"></label><label>DATE<input name="log_date" type="date" value="${today()}"></label><label>REFLECTION<textarea name="reflection" rows="3" placeholder="What did you work through?"></textarea></label>${actions()}`,async e=>{e.preventDefault();await api('/learning/lessons/'+id+'/study',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});learningPaths=await api('/learning/paths');renderLearning();renderOverview();openLearningLesson(id);toast('Study time recorded.')});bindCancel()}

function renderSessions(){$('#sessionHistory').innerHTML=sessions.length?sessions.slice(0,30).map(s=>`<div class="history-row"><div class="history-date">${localDate(s.session_date)}</div><div class="history-copy"><strong>${esc(s.focus)}</strong>${s.reflection?`<p>${esc(s.reflection)}</p>`:''}</div><span class="history-min">${esc(s.minutes)}m</span></div>`).join(''):'<div class="empty">Your focus sessions will find their home here.</div>'}
function renderNotes(){const query=($('#noteSearch')?.value||'').toLowerCase();const found=notes.filter(n=>(n.title+' '+n.body).toLowerCase().includes(query));$('#noteCount').textContent=`${found.length} ENTRIES`;$('#notesGrid').innerHTML=found.length?found.map(n=>`<article class="note-card" data-edit-note="${n.id}"><span class="note-date">UPDATED ${new Date(n.updated_at.replace(' ','T')+'Z').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}).toUpperCase()}</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><div class="note-bottom"><span>PERSONAL LIBRARY</span><span>OPEN ↗</span></div></article>`).join(''):'<div class="empty">Your library is waiting for its first idea.</div>';$$('[data-edit-note]').forEach(c=>c.onclick=()=>openNote(Number(c.dataset.editNote)))}$('#noteSearch').oninput=renderNotes;
function renderGoals(){$('#goalsGrid').innerHTML=goals.length?goals.map(g=>`<article class="goal-card ${g.status==='completed'?'completed':''}"><div class="kicker">${g.status==='completed'?'ACHIEVED':'ACTIVE COMMITMENT'}</div><h3>${esc(g.title)}</h3><p>${esc(g.detail)}</p><div class="goal-meta"><span>${g.target_date?'TARGET · '+localDate(g.target_date):'NO DEADLINE'}</span><button data-goal-toggle="${g.id}" data-status="${esc(g.status)}">${g.status==='completed'?'Reopen':'Mark achieved'}</button><button data-goal-delete="${g.id}" aria-label="Delete goal">×</button></div></article>`).join(''):'<div class="empty">Add a goal worth returning to. Keep it meaningful and measurable.</div>';$$('[data-goal-toggle]').forEach(b=>b.onclick=async()=>{await api('/goals/'+b.dataset.goalToggle,{method:'PATCH',body:JSON.stringify({status:b.dataset.status==='completed'?'active':'completed'})});goals=await api('/goals');renderGoals();renderLeaderboard();toast('Commitment updated.')});$$('[data-goal-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this goal?')){await api('/goals/'+b.dataset.goalDelete,{method:'DELETE'});goals=await api('/goals');renderGoals()}})}
async function renderHabits(){habits=await api('/habits?date='+today());const done=habits.filter(h=>h.done).length;$('#habitCount').textContent=`${done} / ${habits.length}`;$('#habitList').innerHTML=habits.map(h=>`<button class="habit-item ${h.done?'done':''}" data-habit="${h.id}"><span>${esc(h.emoji)}</span>${esc(h.title)}<span>${h.done?'✓':'○'}</span></button>`).join('');if($('#habitManager'))$('#habitManager').innerHTML=habits.map(h=>`<div class="habit-manager-row"><span>${esc(h.emoji)} &nbsp; ${esc(h.title)}</span><button data-remove-habit="${h.id}" title="Remove ritual">×</button></div>`).join('');$$('[data-habit]').forEach(b=>b.onclick=async()=>{await api('/habits/'+b.dataset.habit+'/toggle',{method:'POST',body:JSON.stringify({date:today()})});renderHabits();renderLeaderboard();toast('Daily ritual updated.')});$$('[data-remove-habit]').forEach(b=>b.onclick=async()=>{if(confirm('Remove this daily ritual? Past check-ins will also be removed.')){await api('/habits/'+b.dataset.removeHabit,{method:'DELETE'});renderHabits();toast('Ritual removed.')}})}
async function renderDeen(){
 const date=$('#deenDate').value||today();deenDate=date;
 const [summary,logs]=await Promise.all([api('/deen/summary?date='+date),api('/deen/quran')]);quranLogs=logs;
 const completed=summary.prayers.filter(p=>p.completed).length;$('#prayerCount').textContent=`${completed} / 5 COMPLETE`;$('#prayerCountLarge').textContent=`${completed}/5`;$('#homePrayerCount').textContent=`${completed} / 5`;$('#homePrayerDots').innerHTML=summary.prayers.map(p=>`<span class="home-prayer-dot ${p.completed?'done':''}" title="${p.prayer}${p.completed?(p.on_time?' · on time':' · completed'):''}">${p.prayer.slice(0,1)}</span>`).join('');const homeMem=logs.filter(x=>x.log_date===date);const homePages=homeMem.reduce((a,x)=>a+Number(x.pages||0),0);$('#homeQuranSummary').textContent=homeMem.length?`${homeMem.length} Qur’an session${homeMem.length===1?'':'s'} · ${homePages} pages recorded`:'No Qur’an sessions logged today.';
 $('#prayerList').innerHTML=summary.prayers.map(p=>`<div class="prayer-row ${p.completed?'is-done':''}"><strong class="prayer-name">${p.prayer}</strong><label class="prayer-state"><input type="checkbox" data-prayer-complete="${p.prayer}" ${p.completed?'checked':''}> Completed</label><label class="prayer-state"><input type="checkbox" data-prayer-time="${p.prayer}" ${p.on_time?'checked':''} ${p.completed?'':'disabled'}> On time</label></div>`).join('');
 $$('[data-prayer-complete]').forEach(c=>c.onchange=async()=>{await api('/deen/prayer',{method:'PATCH',body:JSON.stringify({date,prayer:c.dataset.prayerComplete,completed:c.checked,on_time:c.checked?undefined:false})});renderDeen()});
 $$('[data-prayer-time]').forEach(c=>c.onchange=async()=>{await api('/deen/prayer',{method:'PATCH',body:JSON.stringify({date,prayer:c.dataset.prayerTime,on_time:c.checked})});renderDeen()});
 $('#tahajjudControls').innerHTML=`<label class="tahajjud-choice ${summary.tahajjud.woke_up?'done':''}"><input type="checkbox" id="tahajjudWake" ${summary.tahajjud.woke_up?'checked':''}> I woke up for Tahajjud</label><label class="tahajjud-choice ${summary.tahajjud.prayed?'done':''}"><input type="checkbox" id="tahajjudPrayed" ${summary.tahajjud.prayed?'checked':''}> I prayed Tahajjud</label>`;
 $('#tahajjudWake').onchange=async e=>{await api('/deen/tahajjud',{method:'PATCH',body:JSON.stringify({date,woke_up:e.target.checked})});renderDeen()};$('#tahajjudPrayed').onchange=async e=>{await api('/deen/tahajjud',{method:'PATCH',body:JSON.stringify({date,prayed:e.target.checked,woke_up:e.target.checked?undefined:summary.tahajjud.woke_up})});renderDeen()};
 const todayLogs=logs.filter(x=>x.log_date===date);const mem=todayLogs.filter(x=>x.activity==='memorisation'),rev=todayLogs.filter(x=>x.activity==='revision');$('#memorisationPages').textContent=mem.reduce((a,x)=>a+Number(x.pages||0),0).toFixed(1).replace(/\.0$/,'');$('#revisionPages').textContent=rev.reduce((a,x)=>a+Number(x.pages||0),0).toFixed(1).replace(/\.0$/,'');$('#quranSessions').textContent=todayLogs.length;
 $('#quranHistory').innerHTML=logs.length?logs.map(x=>`<article class="quran-entry"><div><small>${x.activity==='memorisation'?'NEW MEMORISATION':'REVISION'} · ${localDate(x.log_date)}</small><strong>${esc(x.surah)}${x.ayah_start?` · Ayah ${esc(x.ayah_start)}${x.ayah_end&&x.ayah_end!==x.ayah_start?'–'+esc(x.ayah_end):''}`:''}</strong><p>${x.pages?`${esc(x.pages)} page${Number(x.pages)===1?'':'s'}`:''}${x.juz?' · Juz '+esc(x.juz):''}${x.reflection?' · '+esc(x.reflection):''}</p></div><button data-quran-delete="${x.id}" title="Delete session">×</button></article>`).join(''):'<div class="empty-quran">Your Qur’an sessions will appear here. Log memorisation and revision separately.</div>';
 $$('[data-quran-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this Quran session record?')){await api('/deen/quran/'+b.dataset.quranDelete,{method:'DELETE'});renderDeen()}});
}
async function renderSelfControl(){
 const data=await api('/self-control?date='+today());
 $('#selfControlCards').innerHTML=data.summary.length?data.summary.map(x=>`<article class="panel self-control-card"><div class="self-card-top"><span class="self-card-symbol">${esc(x.symbol||'◇')}</span><span class="self-card-label">FREEDOM TRACKER</span><button class="self-start-edit" data-self-edit="${x.id}">EDIT NAME ↗</button></div><h3 class="self-habit-name">${esc(x.name)}</h3><div class="self-streak"><strong>${x.streak}</strong><span>day${x.streak===1?'':'s'} free</span></div><div class="self-streak-caption">${x.last_slip?'Since your last reset':'Since you began tracking'} · ${localDate(x.last_slip||x.start_date)}</div><div class="self-card-stats"><div><b>${x.longest_days}</b><small>BEST STREAK</small></div><div><b>${x.today?.outcome==='clean'?'✓':x.today?.outcome==='slip'?'↻':'—'}</b><small>TODAY</small></div></div><div class="self-card-actions"><button class="btn-secondary" data-self-clean="${x.id}" ${x.today?.outcome==='clean'||x.today?.outcome==='slip'?'disabled':''}>${x.today?.outcome==='clean'?'✓ Day recorded':x.today?.outcome==='slip'?'↻ Reset recorded today':'Mark today clean'}</button><button class="self-slip-btn" data-self-slip="${x.id}">Log a slip</button></div><div class="self-card-tools"><button data-self-start="${x.id}">Change start date</button><button class="danger" data-self-remove="${x.id}">Remove tracker</button></div></article>`).join(''):'<div class="freedom-empty panel"><span>◇</span><h2>Your freedom, your rules.</h2><p>Add the habits you want to leave behind. Name each tracker yourself, then mark clean days or record a slip whenever you need to.</p><button class="btn-primary" id="emptyAddFreedom">＋ Create your first tracker</button></div>';
 $('#selfControlHistory').innerHTML=data.logs.length?data.logs.slice(0,35).map(l=>`<article class="self-history-row"><div><strong>${esc(l.tracker_name)}</strong><small>${localDate(l.log_date)} · ${l.outcome==='clean'?'Day recorded clean':'Reset recorded'}${l.trigger?' · '+esc(l.trigger):''}</small></div><span class="self-outcome ${esc(l.outcome)}">${l.outcome==='clean'?'CLEAN':'RESET'}</span><button data-self-delete-entry="${l.id}" title="Delete record">×</button></article>`).join(''):'<div class="empty">Your check-ins will appear here. Start whenever you are ready.</div>';
 $$('[data-self-clean]').forEach(b=>b.onclick=async()=>{await api(`/self-control/${b.dataset.selfClean}/checkin`,{method:'POST',body:JSON.stringify({outcome:'clean'})});renderSelfControl();toast('Today recorded. Keep going, one choice at a time.')});
 $$('[data-self-slip]').forEach(b=>b.onclick=()=>selfSlipForm(b.dataset.selfSlip,data.summary.find(x=>String(x.id)===b.dataset.selfSlip)?.name||'this habit'));
 $$('[data-self-edit]').forEach(b=>b.onclick=()=>editFreedomHabit(data.summary.find(x=>String(x.id)===b.dataset.selfEdit)));
 $$('[data-self-start]').forEach(b=>b.onclick=()=>selfStartForm(b.dataset.selfStart,data.summary.find(x=>String(x.id)===b.dataset.selfStart)?.start_date||today()));
 $$('[data-self-remove]').forEach(b=>b.onclick=async()=>{const item=data.summary.find(x=>String(x.id)===b.dataset.selfRemove);if(item&&confirm(`Remove “${item.name}” and its check-in history? This cannot be undone.`)){await api('/self-control/'+b.dataset.selfRemove,{method:'DELETE'});renderSelfControl();toast('Tracker removed.')}});
 $$('[data-self-delete-entry]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this check-in record?')){await api('/self-control/entries/'+b.dataset.selfDeleteEntry,{method:'DELETE'});renderSelfControl();toast('Record deleted.')}});
 $('#emptyAddFreedom')?.addEventListener('click',addFreedomHabit);
}
function addFreedomHabit(){modal('FREEDOM / NEW TRACKER','What do you want to leave behind?',`<p class="self-modal-copy">Create a tracker for any habit or behaviour you want to change. You can rename it later.</p><label>TRACKER NAME<input name="name" required maxlength="60" placeholder="e.g. No late-night scrolling"></label><label>SYMBOL <input name="symbol" maxlength="4" value="◇" placeholder="◇"></label><label>START COUNTING FROM<input name="start_date" type="date" value="${today()}" max="${today()}" required></label><div class="form-actions"><button type="button" class="btn-cancel" id="cancelModal">Cancel</button><button class="btn-primary">Create tracker <span>→</span></button></div>`,async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));await api('/self-control',{method:'POST',body:JSON.stringify(d)});closeModal();renderSelfControl();toast('Your new tracker is ready.')});bindCancel()}
function editFreedomHabit(item){if(!item)return;modal('FREEDOM / PERSONALISE','Rename your tracker',`<label>TRACKER NAME<input name="name" required maxlength="60" value="${esc(item.name)}"></label><label>SYMBOL<input name="symbol" maxlength="4" value="${esc(item.symbol||'◇')}"></label><div class="form-actions"><button type="button" class="btn-cancel" id="cancelModal">Cancel</button><button class="btn-primary">Save changes <span>→</span></button></div>`,async e=>{e.preventDefault();await api('/self-control/'+item.id,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(form)))});closeModal();renderSelfControl();toast('Tracker updated.')});bindCancel()}
function selfSlipForm(id,name){modal('FREEDOM / HONEST CHECK-IN','Record a reset',`<p class="self-modal-copy">For <strong>${esc(name)}</strong>. This is information, not a verdict. Notice what happened and choose your next step without punishing yourself.</p><label>DATE<input name="date" type="date" value="${today()}" max="${today()}" required></label><label>URGE LEVEL BEFORE (OPTIONAL)<select name="urge_level"><option value="0">Prefer not to say</option><option value="1">1 · Low</option><option value="2">2</option><option value="3">3 · Moderate</option><option value="4">4</option><option value="5">5 · Intense</option></select></label><label>WHAT CONTRIBUTED? (OPTIONAL)<select name="trigger"><option value="">Prefer not to record</option><option>Stress</option><option>Boredom</option><option>Loneliness</option><option>Late-night phone use</option><option>Social media / online content</option><option>Being alone</option><option>Difficulty sleeping</option><option>Other</option></select></label><label>WHAT COULD HELP NEXT TIME?<textarea name="response" rows="2" placeholder="A small change you could try…"></textarea></label><label>NOTE (OPTIONAL)<textarea name="note" rows="2" placeholder="Anything you want to remember…"></textarea></label><div class="form-actions"><button type="button" class="btn-cancel" id="cancelModal">Cancel</button><button class="btn-primary">Save honestly <span>→</span></button></div>`,async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));d.outcome='slip';d.urge_level=Number(d.urge_level||0);await api(`/self-control/${id}/checkin`,{method:'POST',body:JSON.stringify(d)});closeModal();renderSelfControl();toast('Record saved. A reset is a return, not the end.')});bindCancel()}
function selfStartForm(id,current){modal('FREEDOM / TRACKING START','Set your starting date',`<p class="self-modal-copy">Choose the date you want this tracker to count from.</p><label>START DATE<input name="start_date" type="date" value="${current}" max="${today()}" required></label><div class="form-actions"><button type="button" class="btn-cancel" id="cancelModal">Cancel</button><button class="btn-primary">Save date <span>→</span></button></div>`,async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));await api(`/self-control/${id}/start`,{method:'PATCH',body:JSON.stringify(d)});closeModal();renderSelfControl();toast('Starting date updated.')});bindCancel()}
$('#addFreedomHabit').onclick=addFreedomHabit;
$('#deenDate').value=today();$('#deenDate').onchange=renderDeen;
function quranForm(){modal('QUR’AN JOURNEY / NEW SESSION','Record your Hifz or revision',`<div class="quran-form"><div class="form-row"><label>ACTIVITY<select name="activity"><option value="memorisation">New memorisation</option><option value="revision">Revision</option></select></label><label>DATE<input name="log_date" type="date" value="${deenDate||today()}" required></label></div><label>SURAH<input name="surah" required placeholder="e.g. At-Tawbah"></label><div class="form-row"><label>START AYAH<input name="ayah_start" type="number" min="1" placeholder="Optional"></label><label>END AYAH<input name="ayah_end" type="number" min="1" placeholder="Optional"></label></div><div class="form-row"><label>PAGES<input name="pages" type="number" min="0" max="100" step="0.5" value="0"></label><label>JUZ<input name="juz" type="number" min="1" max="30" placeholder="Optional"></label></div><label>REFLECTION / NOTES<textarea name="reflection" rows="2" placeholder="What did you cover? Anything to revisit?"></textarea></label>${actions()}</div>`,async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));for(const k of ['ayah_start','ayah_end','juz'])d[k]=d[k]?Number(d[k]):null;d.pages=Number(d.pages||0);await api('/deen/quran',{method:'POST',body:JSON.stringify(d)});closeModal();await renderDeen();toast('Qur’an session recorded.')});bindCancel()}
$('#addQuranLog').onclick=quranForm;
const backdrop=$('#modalBackdrop'),form=$('#modalForm');function modal(kicker,title,html,submit){$('#modalKicker').textContent=kicker;$('#modalTitle').textContent=title;form.innerHTML=html;backdrop.classList.add('open');form.onsubmit=submit;const first=form.querySelector('input,textarea');setTimeout(()=>first?.focus(),60)}function closeModal(){backdrop.classList.remove('open');form.onsubmit=null}$('#closeModal').onclick=closeModal;backdrop.onclick=e=>{if(e.target===backdrop)closeModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal();$('#searchBackdrop').classList.remove('open')}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}});
function actions(){return `<div class="form-actions"><button type="button" class="btn-cancel" id="cancelModal">Cancel</button><button class="btn-primary">Save <span>→</span></button></div>`}function bindCancel(){$('#cancelModal').onclick=closeModal}
function taskForm(){modal('MY WORK / NEW ITEM','Give the next step a name',`<label>TASK TITLE<input name="title" required placeholder="What needs to move forward?"></label><label>DETAILS<textarea name="detail" rows="3" placeholder="What does done look like?"></textarea></label><div class="form-row"><label>CATEGORY<select name="category"><option>Learning</option><option>Personal</option><option>Practice</option><option>Business</option><option>Research</option><option>Review</option></select></label><label>DUE DATE<input name="due_date" type="date"></label></div>${actions()}`,async e=>{e.preventDefault();await api('/tasks',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});tasks=await api('/tasks');renderTasks();renderOverview();closeModal();toast('Added to your work.')});bindCancel()}
$('#newTaskBtn').onclick=taskForm;$('#quickAddTask').onclick=taskForm;
function openNote(id){editingNote=notes.find(n=>n.id===id)||null;modal('PERSONAL LIBRARY',editingNote?'Edit your entry':'Capture a thought',`<label>TITLE<input name="title" required value="${esc(editingNote?.title||'')}" placeholder="Give the thought a name"></label><label>YOUR THOUGHT<textarea name="body" rows="8" placeholder="Capture a concept, question, lesson or idea…">${esc(editingNote?.body||'')}</textarea></label><div class="form-actions">${editingNote?'<button type="button" class="btn-cancel" id="deleteNote">Delete</button>':''}<button type="button" class="btn-cancel" id="cancelModal">Cancel</button><button class="btn-primary">Save entry <span>→</span></button></div>`,async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));if(editingNote)await api('/notes/'+editingNote.id,{method:'PUT',body:JSON.stringify(d)});else await api('/notes',{method:'POST',body:JSON.stringify(d)});notes=await api('/notes');renderNotes();closeModal();toast('Saved to your library.')});bindCancel();if(editingNote)$('#deleteNote').onclick=async()=>{if(confirm('Delete this entry?')){await api('/notes/'+editingNote.id,{method:'DELETE'});notes=await api('/notes');renderNotes();closeModal();toast('Entry deleted.')}}}
$('#newNoteBtn').onclick=()=>openNote(null);$('#quickNote').onclick=()=>openNote(null);
$('#newGoalBtn').onclick=()=>modal('THE LONG GAME / NEW COMMITMENT','What are you building towards?',`<label>GOAL<input name="title" required placeholder="e.g. Build a skill or reach a meaningful milestone"></label><label>WHY IT MATTERS<textarea name="detail" rows="3" placeholder="Describe what achieving this would mean…"></textarea></label><label>TARGET DATE<input name="target_date" type="date"></label>${actions()}`,async e=>{e.preventDefault();await api('/goals',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});goals=await api('/goals');renderGoals();closeModal();toast('A new commitment is on the horizon.')});
$('#editNorthStar').onclick=()=>switchPage('settings');
function addHabit(){modal('DAILY RITUAL / NEW','Add a small promise',`<label>RITUAL<input name="title" required maxlength="60" placeholder="e.g. Review my Qur’an memorisation"></label><label>SYMBOL <input name="emoji" maxlength="4" value="✦" placeholder="✦"></label>${actions()}`,async e=>{e.preventDefault();await api('/habits',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(form)))});renderHabits();closeModal();toast('Daily ritual added.')});bindCancel()}$('#addHabit').onclick=addHabit;$('#addHabitSettings').onclick=addHabit;
$('#profileForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.username=(d.username||'').trim().replace(/^@/,'');if(d.username&&!/^[A-Za-z0-9_]{3,24}$/.test(d.username)){toast('Username must be 3–24 letters, numbers or underscores.');return}d.leaderboard_name=(d.leaderboard_name||'').trim().slice(0,24);d.leaderboard_public=$('#leaderboardPublicInput').checked?'1':'0';const previousReligion=settings.religion;settings=await api('/settings',{method:'PATCH',body:JSON.stringify(d)});const {error}=await supabaseClient.auth.updateUser({data:{full_name:d.display_name,username:d.username}});if(error)console.warn('Profile metadata sync:',error.message);$('#northStarText').textContent=settings.north_star;applyReligionVisibility();applyWidgets();renderFeatureToggles();applyFeatureVisibility();if(settings.religion==='islam'||isAdmin)renderDeen();if(settings.religion==='christianity'||isAdmin)renderFaith();if(previousReligion!==settings.religion)switchPage(settings.religion==='islam'?'deen':settings.religion==='christianity'?'faith':'home');renderCalendar();updateClock();toast('Your residence, your rules.')};
async function exportWorkspace(){try{const {data:{session}}=await supabaseClient.auth.getSession();if(!session)throw new Error('Sign in again before exporting your workspace.');const response=await fetch('/api/export',{headers:{Authorization:`Bearer ${session.access_token}`}});if(!response.ok){let detail={};try{detail=await response.json()}catch{}throw new Error(detail.error||'Your backup could not be exported.')}const blob=await response.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download='personal-os-backup.json';document.body.appendChild(link);link.click();link.remove();URL.revokeObjectURL(url);toast('Your complete backup has been downloaded.')}catch(error){toast(error.message||'Your backup could not be exported.')}}$('#exportBtn').onclick=$('#settingsExport').onclick=exportWorkspace;
$('#settingsImport').onclick=()=>$('#backupImportFile').click();
$('#backupImportFile').onchange=async event=>{const file=event.target.files?.[0];if(!file)return;try{if(file.size>10*1024*1024)throw new Error('Backup files must be 10 MB or smaller.');if(!confirm('Import this backup and replace the records in your current workspace? Export your current data first if you want to keep it.'))return;const backup=JSON.parse(await file.text());const result=await api('/import',{method:'POST',body:JSON.stringify(backup)});toast(`Imported ${result.imported} records. Refreshing your workspace…`);setTimeout(()=>location.reload(),700)}catch(error){toast(error.message||'The backup could not be imported.')}finally{event.target.value=''}};
const presets=$$('.timer-presets button');function setTimer(min){pauseTimer();timer.duration=min*60;timer.left=timer.duration;presets.forEach(b=>b.classList.toggle('selected',Number(b.dataset.minutes)===min));drawTimer()};function drawTimer(){const m=Math.floor(timer.left/60),s=timer.left%60;$('#timerClock').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;const p=timer.duration?1-timer.left/timer.duration:0;$('#timerProgress').style.background=`conic-gradient(var(--focus) ${p*360}deg,#252a32 ${p*360}deg)`;$('#timerState').textContent=timer.running?'IN SESSION':timer.left===0?'SESSION COMPLETE':'READY WHEN YOU ARE';$('#timerStart').innerHTML=timer.running?'Pause session <span>Ⅱ</span>':'Begin session <span>→</span>'};function pauseTimer(){timer.running=false;clearInterval(timer.interval);timer.interval=null;drawTimer()}function startTimer(){if(timer.running){pauseTimer();return}if(!$('#timerFocus').value.trim()){$('#timerFocus').focus();toast('Give this session a focus first.');return}timer.running=true;drawTimer();timer.interval=setInterval(async()=>{timer.left--;drawTimer();if(timer.left<=0){pauseTimer();await saveTimedSession(timer.duration/60);toast('Session complete. Your focus time is recorded.');try{new AudioContext().resume().then(()=>{}); }catch{} }},1000)}async function saveTimedSession(min){const focus=$('#timerFocus').value.trim();await api('/sessions',{method:'POST',body:JSON.stringify({session_date:today(),minutes:Math.round(min),focus,reflection:'Completed a timed focus session.'})});sessions=await api('/sessions');renderSessions();renderOverview();renderLeaderboard()}$('#timerStart').onclick=startTimer;$('#timerReset').onclick=()=>{setTimer(50);toast('Timer reset.')};presets.forEach(b=>b.onclick=()=>setTimer(Number(b.dataset.minutes)));$('#beginFocus').onclick=()=>switchPage('focus');setTimer(50);
function openSearch(){$('#searchBackdrop').classList.add('open');$('#globalSearch').value='';$('#searchResults').innerHTML='<p>Search across your tasks, notes and learning path.</p>';setTimeout(()=>$('#globalSearch').focus(),50)}$('#searchOpen').onclick=openSearch;$('#searchBackdrop').onclick=e=>{if(e.target===$('#searchBackdrop'))$('#searchBackdrop').classList.remove('open')};$('#globalSearch').oninput=()=>{const q=$('#globalSearch').value.toLowerCase().trim();if(!q){$('#searchResults').innerHTML='<p>Start typing to search your residence.</p>';return}const hits=[...tasks.filter(t=>(t.title+' '+t.detail).toLowerCase().includes(q)).map(t=>({title:t.title,type:'TASK',page:'tasks'})),...notes.filter(n=>(n.title+' '+n.body).toLowerCase().includes(q)).map(n=>({title:n.title,type:'NOTE',page:'library'})),...modules.filter(m=>m.title.toLowerCase().includes(q)).map(m=>({title:m.title,type:'LEARNING',page:'learning'})),...goals.filter(g=>g.title.toLowerCase().includes(q)).map(g=>({title:g.title,type:'GOAL',page:'goals'})),...quranLogs.filter(x=>(x.surah+' '+x.activity+' '+x.reflection).toLowerCase().includes(q)).map(x=>({title:x.surah,type:'QUR’AN',page:'deen'}))];$('#searchResults').innerHTML=hits.length?hits.slice(0,12).map(h=>`<button class="search-result" data-result-page="${h.page}"><span>↗</span>${esc(h.title)}<small>${h.type}</small></button>`).join(''):'<p>No matching entries in your residence.</p>';$$('[data-result-page]').forEach(b=>b.onclick=()=>{$('#searchBackdrop').classList.remove('open');switchPage(b.dataset.resultPage)})};
function setAuthView(view){const signup=view==='signup';if(signup)setSignupStep(1);$('#signupTheme').onchange=()=>applyTheme($('#signupTheme').value,false);$('#loginForm').classList.toggle('hidden',signup);$('#signupForm').classList.toggle('hidden',!signup);$('#resetRequestForm').classList.add('hidden');$('#newPasswordForm').classList.add('hidden');$$('[data-auth-view]').forEach(b=>b.classList.toggle('active',b.dataset.authView===view));$('#authTitle').innerHTML=signup?'Create your <em>account.</em>':'Welcome <em>back.</em>';$('.auth-card>p').textContent=signup?'Create your identity for your personal workspace.':'Sign in to enter your private workspace.';$('#authMessage').textContent='';$('#signupMessage').textContent='Create your account to begin.';}

