$('#newPasswordForm').addEventListener('submit',async event=>{event.preventDefault();const button=event.currentTarget.querySelector('button[type=submit]'),message=$('#newPasswordMessage'),password=$('#newPassword').value;if(password.length<8){message.textContent='Use at least 8 characters.';return;}if(password!==$('#confirmNewPassword').value){message.textContent='The passwords do not match.';return;}button.disabled=true;message.textContent='Updating your password…';try{const {error}=await supabaseClient.auth.updateUser({password});if(error)throw error;message.textContent='Password updated. You can now sign in with your new password.';await supabaseClient.auth.signOut();history.replaceState(null,'',window.location.pathname);setAuthView('login');$('#authMessage').textContent='Your password has been changed. Sign in with your new password.';}catch(error){message.textContent=error.message||'Could not update your password. Request a new reset link.';}finally{button.disabled=false;}});

