function wireSignupTourDemo(item){const host=$('#signupTourPreview');if(!host||item.guide)return;const copy={calendar:['Mark today complete','Today is now marked in your sample calendar.'],learning:['Complete next checkpoint','Checkpoint completed — your sample path moved forward.'],tasks:['Complete this task','Task checked off. That is how progress is recorded.'],focus:['Start a sample session','Sample focus session started. In Atlas, completed sessions are saved to your history.'],library:['Save sample note','Your sample note is ready to keep in your private library.'],goals:['Update goal progress','Your sample goal progress has been updated.'],selfcontrol:['Log today’s check-in','Check-in recorded in this preview. Your real entries stay private.'],rankings:['Preview ranking privacy','Ranking visibility is optional and controlled in Settings → Profile.'],deen:['Log a practice check-in','Sample practice check-in recorded.'],faith:['Log a reflection check-in','Sample reflection recorded.']};const action=copy[item.key]||copy.calendar;const control=item.key==='library'?'<input type="text" maxlength="80" placeholder="Write a sample note…" aria-label="Try writing a sample note">':item.key==='goals'?'<input type="range" min="0" max="100" value="65" aria-label="Adjust sample goal progress">':item.key==='tasks'?'<label class="tour-demo-check"><input type="checkbox"> Define the project outcome</label>':'<button type="button" data-tour-demo-action>'+action[0]+'</button>';host.insertAdjacentHTML('beforeend','<div class="tour-demo-actions">'+control+'<small id="tourDemoStatus">Try the control to see how it works.</small></div>');const status=$('#tourDemoStatus');const button=host.querySelector('[data-tour-demo-action]');if(button)button.onclick=()=>{button.classList.toggle('active');button.textContent=button.classList.contains('active')?'✓ Tried it':action[0];status.textContent=action[1];};const check=host.querySelector('.tour-demo-check input');if(check)check.onchange=()=>status.textContent=check.checked?'Task checked off in this sample.':'Task marked incomplete in this sample.';const input=host.querySelector('input[type=text]');if(input)input.oninput=()=>status.textContent=input.value?'Sample note: '+input.value:'Type a note to preview capture.';const range=host.querySelector('input[type=range]');if(range)range.oninput=()=>status.textContent='Sample goal progress: '+range.value+'%';}
function openOnboardingTour(){const selected=new Set(enabledFeatures());$$('[data-signup-feature]').forEach(input=>input.checked=selected.has(input.dataset.signupFeature));$('#signupReligion').value=settings.religion||authUser?.user_metadata?.religion||'none';$('#signupTheme').value=settings.theme||authUser?.user_metadata?.theme||'nocturnal-amethyst';signupTourIndex=0;renderSignupTour();const tour=$('#onboardingTour');tour.classList.add('active');tour.setAttribute('aria-hidden','false');document.body.classList.add('onboarding-active');}
async function finishOnboardingTour(){const next=$('#signupTourNext'),skip=$('#signupTourSkip');if(next)next.disabled=true;if(skip)skip.disabled=true;try{const features=$$('[data-signup-feature]:checked').map(input=>input.dataset.signupFeature);settings=await api('/settings',{method:'PATCH',body:JSON.stringify({features,theme:$('#signupTheme').value||settings.theme||'nocturnal-amethyst'})});const {data,error}=await supabaseClient.auth.updateUser({data:{onboarding_completed:true,onboarding_version:ONBOARDING_ROLLOUT_VERSION,enabled_features:features}});if(error)throw error;if(data?.user)authUser=data.user;applyFeatureVisibility();renderFeatureToggles();$('#onboardingTour').classList.remove('active');$('#onboardingTour').setAttribute('aria-hidden','true');document.body.classList.remove('onboarding-active');toast('Your Atlas is ready. Your workspace choices have been saved.');showNextAnnouncement();}catch(error){toast('Could not save your walkthrough choices: '+error.message);if(next)next.disabled=false;if(skip)skip.disabled=false;}}
function passwordChecks(value){return {length:value.length>=8,letter:/[A-Za-z]/.test(value),number:/[0-9]/.test(value),symbol:/[^A-Za-z0-9]/.test(value)}}
function updatePasswordStrength(){const value=$('#signupPassword').value,checks=passwordChecks(value),score=Object.values(checks).filter(Boolean).length,level=score===4?'strong':score>=2?'medium':'weak',panel=$('#passwordGuidance'),label=$('#passwordStrengthLabel'),fill=$('#passwordStrengthFill');panel.dataset.strength=value?level:'empty';label.textContent=value?(level==='strong'?'Strong':level==='medium'?'Getting there':'Weak'):'Not checked';fill.style.width=(score*25)+'%';$$('[data-password-rule]').forEach(item=>{const key=item.dataset.passwordRule;item.classList.toggle('passed',checks[key])});return Object.values(checks).every(Boolean)}
$('#signupPassword').addEventListener('input',updatePasswordStrength);updatePasswordStrength();
$('#signupContinue').onclick=()=>{const account=$('#signupStepAccount');if(!updatePasswordStrength()){ $('#signupMessage').textContent='Your password needs at least 8 characters, a letter, a number and a symbol.';$('#signupPassword').focus();return;}const invalid=account.querySelector('input:invalid');if(!invalid)setSignupStep(2);else invalid.reportValidity();};$('#signupBack').onclick=()=>setSignupStep(1);$('#signupReligion').onchange=updateSignupFaithOption;setSignupStep(1);
$$('[data-auth-view]').forEach(b=>b.addEventListener('click',()=>setAuthView(b.dataset.authView)));
$('#signupForm').addEventListener('submit',async event=>{event.preventDefault();if($('#signupStepSetup').classList.contains('hidden')){const invalid=$('#signupStepAccount').querySelector('input:invalid');if(invalid){invalid.reportValidity();return}setSignupStep(2);return}const button=event.currentTarget.querySelector('#signupStepSetup button[type="submit"]');const message=$('#signupMessage');const name=$('#signupName').value.trim(),username=$('#signupUsername').value.trim().replace(/^@/,''),email=$('#signupEmail').value.trim(),password=$('#signupPassword').value,religion=$('#signupReligion').value,theme=$('#signupTheme').value,features=$('[data-signup-feature]:checked').map(input=>input.dataset.signupFeature);if(!Object.values(passwordChecks(password)).every(Boolean)){message.textContent='Password must have at least 8 characters, a letter, a number and a symbol.';setSignupStep(1);updatePasswordStrength();return}if(!/^[A-Za-z0-9_]{3,24}$/.test(username)){message.textContent='Username must be 3–24 letters, numbers or underscores.';return}if(!religion){message.textContent='Choose a religious experience to continue.';return}button.disabled=true;button.textContent='Creating your account…';message.textContent='';const {data,error}=await supabaseClient.auth.signUp({email,password,options:{data:{full_name:name,username,religion,theme,enabled_features:features,onboarding_completed:false},emailRedirectTo:AUTH_REDIRECT_URL}});button.disabled=false;button.innerHTML='Create your account <span>→</span>';if(error){message.textContent=error.message;return}if(data.session){await enterWorkspace(data.session)}else{$('#loginEmail').value=email;setAuthView('login');$('#authMessage').textContent='Your account is ready. Check your inbox to confirm your email, then sign in.';}});
async function enterWorkspace(session){
  const message=$('#authMessage');
  const welcomeMessages=[['Welcome back.','Restoring your personal environment…'],['Your workspace is waking up.','Bringing your plans and progress back into focus…'],['Picking up where you left off.','Syncing your latest activity…'],['Good to have you back.','Preparing your next step…'],['Your progress is right where you left it.','Loading your private residence…']];
  const welcome=welcomeMessages[Math.floor(Math.random()*welcomeMessages.length)];
  $('#welcomeLoaderTitle').textContent=welcome[0];$('#welcomeLoaderMessage').textContent=welcome[1];$('#welcomeLoader').classList.remove('hidden');
  const welcomeStarted=Date.now();
  try {
    const response=await fetch('/api/session',{headers:{Authorization:`Bearer ${session.access_token}`}});
    const result=await response.json();
    if(!response.ok) throw new Error(result.error||'Access denied.');
    authUser=session.user||result.user;isAdmin=result.role==='admin';const needsFirstRunTour=Number(authUser?.user_metadata?.onboarding_version||0)<ONBOARDING_ROLLOUT_VERSION;
    if(isAdmin){
      try{await supabaseClient.auth.updateUser({data:{username:'admin'}});authUser={...authUser,user_metadata:{...(authUser.user_metadata||{}),username:'admin'}};await api('/settings',{method:'PATCH',body:JSON.stringify({username:'admin'})});}
      catch(error){console.warn('Could not synchronise administrator username:',error.message);}
    }$('#adminNav').classList.toggle('hidden',!isAdmin);document.body.classList.toggle('is-admin',isAdmin);$('#adminFeedbackInbox').classList.toggle('hidden',!isAdmin);
    document.body.classList.remove('auth-locked');
    $('#authGate').classList.add('hidden');
    await load();await loadFeedbackHistory();if(isAdmin)await loadAdminFeedback();await loadAnnouncements(false);
    if(isAdmin||needsFirstRunTour)openOnboardingTour();
    api('/login-event',{method:'POST',body:'{}'}).catch(()=>{});
    api('/welcome',{method:'POST',body:'{}'}).catch(()=>{});
    await new Promise(resolve=>setTimeout(resolve,Math.max(0,1400-(Date.now()-welcomeStarted))));
    $('#welcomeLoader').classList.add('hidden');
    if(!isAdmin&&!needsFirstRunTour)showNextAnnouncement();
    if(signupConfirmationPending){toast('Email confirmed — thank you for joining Amstreem. Your residence is ready.');history.replaceState(null,'',window.location.pathname+window.location.search);}
  } catch(error) {
    $('#welcomeLoader').classList.add('hidden');
    await supabaseClient.auth.signOut();
    if(message) message.textContent=error.message;
  }
}

function renderAdminUsers(){const body=$('#adminUserRows'),filter=$('#adminMailFilter')?.value||'new';const visible=adminUsers.filter(u=>filter==='all'||(filter==='sent'?u.thank_you_status==='sent':u.thank_you_status!=='sent'&&u.thank_you_status!=='pending'));$('#adminNewMailCount').textContent=adminUsers.filter(u=>u.email&&u.thank_you_status!=='sent'&&u.thank_you_status!=='pending'&&u.id!==authUser?.id).length;$('#adminSentMailCount').textContent=adminUsers.filter(u=>u.thank_you_status==='sent').length;body.innerHTML=visible.length?visible.map(u=>{const sent=u.thank_you_status==='sent';const status=sent?'Sent'+(u.thank_you_sent_at?' · '+new Date(u.thank_you_sent_at).toLocaleDateString():''):(u.thank_you_status==='pending'?'Sending / verify':'Not sent');return '<tr><td><input type="checkbox" class="admin-user-check" value="'+esc(u.id)+'" aria-label="Select '+esc(u.name)+'" '+(sent||u.thank_you_status==='pending'?'disabled':'')+'></td><td>'+esc(u.name)+'</td><td>'+(u.username?'@'+esc(u.username):'—')+'</td><td>'+esc(u.email)+'</td><td>'+(u.created_at?new Date(u.created_at).toLocaleDateString():'—')+'</td><td><span class="admin-status '+(u.email_confirmed?'confirmed':'pending')+'">'+(u.email_confirmed?'Verified':'Unverified')+'</span></td><td><span class="admin-status '+(sent?'confirmed':'pending')+'">'+esc(status)+'</span></td></tr>';}).join(''):'<tr><td colspan="7">No accounts in this view.</td></tr>';$('#adminSelectAll').checked=false;}
async function loadAdminUsers(){const body=$('#adminUserRows');loadAdminAnalytics();body.innerHTML='<tr><td colspan="7">Loading account directory…</td></tr>';try{const data=await api('/admin/users');adminUsers=data.users||[];if(!data.email_configured)$('#adminMailStatus').textContent='Email is not configured yet. Add RESEND_API_KEY and EMAIL_FROM in Render to activate sending.';else $('#adminMailStatus').textContent='Email sender is configured. New recipients are ready to receive the thank-you message.';$('#adminUserCount').textContent=adminUsers.length;$('#adminConfirmedCount').textContent=adminUsers.filter(u=>u.email_confirmed).length;renderAdminUsers();}catch(e){body.innerHTML='<tr><td colspan="7">'+esc(e.message)+'</td></tr>';}}
async function loadAdminAnalytics(){try{const x=await api('/admin/analytics');$('#adminActiveToday').textContent=x.activeToday;$('#adminActiveWeek').textContent=x.activeWeek;$('#adminActiveMonth').textContent=x.activeMonth;$('#adminLoginCount').textContent=x.loginsToday;$('#adminTopStreak').textContent=x.topCurrent+' days';$('#adminBestStreak').textContent=x.bestStreak+' days';}catch(e){['adminActiveToday','adminActiveWeek','adminActiveMonth','adminLoginCount','adminTopStreak','adminBestStreak'].forEach(id=>$('#'+id).textContent='—');console.warn('Admin analytics unavailable:',e.message)}}
$('#refreshAdmin').onclick=loadAdminUsers;
$('#adminMailFilter').onchange=renderAdminUsers;$('#adminSelectAll').onchange=()=>document.querySelectorAll('.admin-user-check:not(:disabled)').forEach(c=>c.checked=$('#adminSelectAll').checked);
async function sendAdminMail(all){const ids=Array.from(document.querySelectorAll('.admin-user-check:checked')).map(x=>x.value);const newCount=adminUsers.filter(u=>u.email&&u.thank_you_status!=='sent'&&u.thank_you_status!=='pending'&&u.id!==authUser?.id).length;if(!all&&!ids.length){$('#adminMailStatus').textContent='Select at least one account that has not received the message.';return}if(!confirm(all?'Send the thank-you message to '+newCount+' accounts that have not received it yet? Already-sent accounts will be skipped.':`Send the thank-you message to ${ids.length} selected new account(s)?`))return;const status=$('#adminMailStatus');status.textContent='Sending…';try{const result=await api('/admin/thank-you',{method:'POST',body:JSON.stringify({all,userIds:all?undefined:ids,subject:$('#adminMailSubject').value,message:$('#adminMailMessage').value})});await loadAdminUsers();status.textContent=`Sent: ${result.sent}. Failed: ${result.failed}. Already sent: ${result.skippedAlreadySent}. Awaiting status check: ${result.skippedPending+result.pending}.`;}catch(e){status.textContent=e.message;}}
$('#adminMarkSent').onclick=async()=>{const ids=Array.from(document.querySelectorAll('.admin-user-check:checked')).map(x=>x.value);if(!ids.length){$('#adminMailStatus').textContent='Select accounts first.';return}if(!confirm('Mark '+ids.length+' selected accounts as already sent? No email will be sent.'))return;try{const result=await api('/admin/thank-you/mark-sent',{method:'POST',body:JSON.stringify({userIds:ids})});await loadAdminUsers();$('#adminMailStatus').textContent='Marked '+result.marked+' account(s) as already sent.';}catch(e){$('#adminMailStatus').textContent=e.message;}};$('#adminMailForm').onsubmit=e=>{e.preventDefault();sendAdminMail(false)};$('#adminMailAll').onclick=()=>sendAdminMail(true);
$('#signOutBtn').addEventListener('click',async()=>{await supabaseClient.auth.signOut();location.reload();});
function showPasswordRecoveryForm(){passwordRecoveryActive=true;document.body.classList.add('auth-locked');$('#authGate').classList.remove('hidden');$('#loginForm').classList.add('hidden');$('#signupForm').classList.add('hidden');$('#resetRequestForm').classList.add('hidden');$('#newPasswordForm').classList.remove('hidden');$('#authTitle').innerHTML='Choose a new <em>password.</em>';$('.auth-card>p').textContent='Finish securing your Atlas account.';}
supabaseClient.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY')showPasswordRecoveryForm();if(event==='SIGNED_OUT'){authUser=null;document.body.classList.add('auth-locked');$('#authGate').classList.remove('hidden');}});
(async()=>{try{const {data,error}=await supabaseClient.auth.getSession();if(error)throw error;if(passwordRecoveryActive){showPasswordRecoveryForm();return;}if(authQueryParams.has('code'))await new Promise(resolve=>setTimeout(resolve,700));if(passwordRecoveryActive){showPasswordRecoveryForm();return;}if(data.session)enterWorkspace(data.session);else if(signupConfirmationPending){setAuthView('login');$('#authMessage').textContent='Email confirmed — thank you for joining Amstreem. You can now sign in.';history.replaceState(null,'',window.location.pathname+window.location.search);}}catch(error){console.error('Could not restore Atlas session:',error);$('#authMessage').textContent='Your link could not be verified or has expired. Return to Forgot password and request a fresh reset link.';}})();
